	@Test
	void aJoinClosedWhileItReadsTheNextBlockSchedulesNothing() throws Exception {
		FedXRepository repository = FedXFactory.newFederation().withMembers(new ArrayList<Endpoint>()).create();
		repository.init();
		ControlledWorkerScheduler<BindingSet> scheduler = new ControlledWorkerScheduler<>(1, "bind-join-close");
		try {
			FederationContext federationContext = repository.getFederationContext();
			QueryInfo queryInfo = new QueryInfo("SELECT * WHERE { ?s ?p ?o }", null, QueryType.SELECT, 0, false,
					federationContext, null, null);
			AtomicInteger tasksRequested = new AtomicInteger();
			ClosingLeftIteration left = new ClosingLeftIteration();
			ControlledWorkerBindJoinBase join = new ControlledWorkerBindJoinBase(scheduler, null, left,
					new BoundSingletonSet(), EmptyBindingSet.getInstance(), queryInfo) {
				@Override
				protected TaskCreator determineTaskCreator(TupleExpr expr, BindingSet bs) {
					return (control, bindings) -> {
						tasksRequested.incrementAndGet();
						throw new AssertionError("A closed join must not schedule a bind join task");
					};
				}
			};
			left.join = join;

			// The join passes its closed check, is closed while the left side reports a binding, and must then stop
			// instead of scheduling a block without bindings.
			assertThatNoException().isThrownBy(join::handleBindings);
			assertThat(tasksRequested).hasValue(0);
		} finally {
			scheduler.shutdown();
			repository.shutDown();
		}
	}

